// K Closest Points to Origin using Min Heap
var heap = AnimatedHeap<Int>(kind: .min)
let points = [[1, 3], [-2, 2], [5, 8]]
let k = 2

func squaredDistance(_ point: [Int]) -> Int {
    return point[0] * point[0] + point[1] * point[1]
}

for p in points {
    heap.insert(squaredDistance(p))
}

var result: [Int] = []
for _ in 0..<k {
    if let dist = heap.extract() {
        result.append(dist)
    }
}
